// Parity of the JS core with the golden files generated by the Python core (shared/golden).
// If the golden files are missing the tests skip with a message; they are never faked.
import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import { buildModel, detect, evaluate, spillDetail, optimize } from "../src/core/index.js";
import { demo, sharedPath, readJson } from "./core-helpers.js";

const goldenFile = (name) => sharedPath("golden", name);
const missing = (name) => !fs.existsSync(goldenFile(name));
const skipMsg = (name) => (missing(name) ? `golden file shared/golden/${name} not found: run python -m custom_components.presence_planner.core.golden` : false);

const { plan } = demo();
const SHARE_TOL = 0.02;       // shares and detect qualities
const POS_TOL = 0.05;         // metres
const ANGLE_TOL = 5;          // degrees
const angDiff = (a, b) => Math.abs(((a - b + 540) % 360) - 180);

function expectClose(actual, expected, tol, label, bad) {
  const a = actual ?? 0;
  if (!(Math.abs(a - expected) <= tol)) bad.push(`${label}: got ${a}, expected ${expected}`);
}

test("parity: detect samples", { skip: skipMsg("demo-detect.json") }, () => {
  const g = readJson(goldenFile("demo-detect.json"));
  const model = buildModel(plan, g.floor_id);
  assert.ok(g.samples.length >= 300, "at least 300 samples");
  const bad = [];
  g.samples.forEach((s, i) => {
    const q = detect(model, s.sensor, s.point, s.opts);
    expectClose(q, s.quality, SHARE_TOL, `sample ${i} (${s.tag})`, bad);
  });
  assert.deepEqual(bad.slice(0, 10), [], `${bad.length} of ${g.samples.length} samples differ`);
});

function compareEvaluate(js, py, label, bad) {
  for (const [rid, room] of Object.entries(py.rooms)) {
    const r = js.rooms[rid];
    if (!r) { bad.push(`${label} room ${rid} missing`); continue; }
    for (const h of Object.keys(room.coverage)) expectClose(r.coverage[h], room.coverage[h], SHARE_TOL, `${label} ${rid} coverage ${h}`, bad);
    for (const h of Object.keys(room.seen)) expectClose(r.seen[h], room.seen[h], SHARE_TOL, `${label} ${rid} seen ${h}`, bad);
    expectClose(r.coverage_mean, room.coverage_mean, SHARE_TOL, `${label} ${rid} coverage_mean`, bad);
    expectClose(r.misfire_risk, room.misfire_risk, SHARE_TOL, `${label} ${rid} misfire_risk`, bad);
    for (const e of new Set([...Object.keys(room.from), ...Object.keys(r.from)])) expectClose(r.from[e], room.from[e] ?? 0, SHARE_TOL, `${label} ${rid} from ${e}`, bad);
    assert.deepEqual(r.own_sensors, room.own_sensors, `${label} ${rid} own_sensors`);
  }
  for (const [eid, s] of Object.entries(py.sensors)) {
    const t = js.sensors[eid];
    if (!t) { bad.push(`${label} sensor ${eid} missing`); continue; }
    assert.equal(t.room, s.room, `${label} ${eid} room`);
    expectClose(t.glass, s.glass, SHARE_TOL, `${label} ${eid} glass`, bad);
    for (const rid of new Set([...Object.keys(s.spill), ...Object.keys(t.spill)])) expectClose(t.spill[rid], s.spill[rid] ?? 0, SHARE_TOL, `${label} ${eid} spill ${rid}`, bad);
  }
  assert.equal(js.zones.length, py.zones.length, `${label} zone count`);
  py.zones.forEach((z, i) => {
    const t = js.zones[i];
    assert.deepEqual([t.name, t.room, t.height], [z.name, z.room, z.height], `${label} zone ${i} identity`);
    expectClose(t.share, z.share, SHARE_TOL, `${label} zone ${z.name}@${z.room}`, bad);
  });
}

test("parity: evaluate with doors open and closed", { skip: skipMsg("demo-evaluate.json") }, () => {
  const g = readJson(goldenFile("demo-evaluate.json"));
  const model = buildModel(plan, g.floor_id);
  const bad = [];
  compareEvaluate(evaluate(model, g.sensors, { ...g.opts, doors: "open" }), g.open, "open", bad);
  compareEvaluate(evaluate(model, g.sensors, { ...g.opts, doors: "closed" }), g.closed, "closed", bad);
  assert.deepEqual(bad.slice(0, 10), [], `${bad.length} values differ`);
});

test("parity: spill detail", { skip: skipMsg("demo-spill.json") }, () => {
  const g = readJson(goldenFile("demo-spill.json"));
  const model = buildModel(plan, g.floor_id);
  const bad = [];
  for (const entry of g.sensors) {
    const js = spillDetail(model, entry.sensor, g.opts);
    const id = entry.sensor.entity_id;
    for (const [rid, e] of Object.entries(entry.spill)) {
      const t = js[rid];
      if (!t) { bad.push(`${id} ${rid} missing`); continue; }
      expectClose(t.total, e.total, SHARE_TOL, `${id} ${rid} total`, bad);
      expectClose(t.walls, e.walls, SHARE_TOL, `${id} ${rid} walls`, bad);
      for (const d of new Set([...Object.keys(e.doors), ...Object.keys(t.doors)])) expectClose(t.doors[d], e.doors[d] ?? 0, SHARE_TOL, `${id} ${rid} door ${d}`, bad);
      assert.deepEqual((t.door_paths || []).map((p) => p.doors), (e.door_paths || []).map((p) => p.doors));
      (e.door_paths || []).forEach((p, i) => expectClose(t.door_paths[i].share, p.share, SHARE_TOL, `${id} ${rid} path ${i}`, bad));
    }
  }
  assert.deepEqual(bad.slice(0, 10), [], `${bad.length} values differ`);
});

function compareOptimize(model, profile, rooms, opts, weight, label, bad) {
  for (const [rid, e] of Object.entries(rooms)) {
    const js = optimize(model, rid, profile, opts, weight);
    const best = js[0], gold = e.best;
    if (!best) { bad.push(`${label} ${rid}: no candidate`); continue; }
    const ok = Math.hypot(best.x - gold.x, best.z - gold.z) <= POS_TOL && (best.mount === "ceiling" || angDiff(best.phi, gold.phi) <= ANGLE_TOL) && best.mount === gold.mount;
    if (!ok) bad.push(`${label} ${rid}: got (${best.x}, ${best.z}, phi ${best.phi}, ${best.mount}, score ${best.score}), expected (${gold.x}, ${gold.z}, phi ${gold.phi}, ${gold.mount}, score ${gold.score})`);
    expectClose(best.score, gold.score, 0.005, `${label} ${rid} score`, bad);
  }
}

test("parity: optimize (best candidate per room)", { skip: skipMsg("demo-optimize.json") }, () => {
  const g = readJson(goldenFile("demo-optimize.json"));
  const model = buildModel(plan, g.floor_id);
  const bad = [];
  compareOptimize(model, g.profile, g.rooms, g.opts, g.weight, g.profile, bad);
  if (g.wall_corner) compareOptimize(model, g.wall_corner.profile, g.wall_corner.rooms, g.opts, g.weight, g.wall_corner.profile, bad);
  assert.deepEqual(bad, [], `${bad.length} optimizer results differ`);
});
